/// Lesson sections for the info page — never shown on the practice screen.
const List<TechniqueSection> feetKickControlLesson = [
  TechniqueSection(
    title: "Why it matters",
    body:
        "The kick is where the band feels the downbeat and where the bass player locks in. A kick that lands exactly under the hi-hat, at the same volume every time, makes even a simple groove sound expensive; a kick that drifts makes the whole band drift.",
  ),
  TechniqueSection(
    title: "How to play it",
    body:
        "Heel up, the ball of the foot on the pedal, and let the leg drop from the hip so the beater strikes and comes straight back off the head — the hi-hat and snare stay exactly as they are while only the foot changes.",
  ),
  TechniqueSection(
    title: "Practice tips",
    body:
        "Line 1 is the reference: kick on 1 and 3 locked to the hat. Lines 2 and 4 move the kick to the \"and\", line 3 and line 5 ask for two strokes in a row (the second one as loud as the first), line 7 is four-on-the-floor. Line 8 puts the kick on 2 and the \"and\" of 4 in its first bar — count out loud so the snare does not pull the foot along — and mixes 1, the \"and\" of 2, the \"a\" of 3 and 4 in its second bar.",
  ),
  TechniqueSection(
    title: "Where you hear it",
    body:
        "AC/DC \"Back in Black\" with Phil Rudd, Led Zeppelin \"When the Levee Breaks\" with John Bonham, and every four-on-the-floor dance track from disco to house.",
  ),
];
